SELECT T2.title, T2.type, T2.price FROM titles T2 JOIN (SELECT T1.title_id FROM sales T1 WHERE strftime('%Y', T1.ord_date) = '1994' GROUP BY T1.title_id HAVING SUM(T1.qty) < (SELECT SUM(T1.qty) / COUNT(DISTINCT T1.title_id) FROM sales T1 WHERE strftime('%Y', T1.ord_date) = '1994')) AS SubQ ON T2.title_id = SubQ.title_id;
