SELECT ABS(AVG(CASE WHEN P.country = 'USA' THEN E.job_lvl END) - AVG(CASE WHEN P.country != 'USA' THEN E.job_lvl END)) AS avg_level_difference FROM employee E JOIN jobs J ON E.job_id = J.job_id JOIN publishers P ON E.pub_id = P.pub_id WHERE J.job_desc = 'Marketing Manager';
