SELECT ABS((SELECT AVG(S.gpa) FROM student S JOIN registration R ON S.student_id = R.student_id JOIN course C ON R.course_id = C.course_id WHERE C.diff = (SELECT MAX(diff) FROM course)) - (SELECT AVG(S.gpa) FROM student S JOIN registration R ON S.student_id = R.student_id JOIN course C ON R.course_id = C.course_id WHERE C.diff = (SELECT MIN(diff) FROM course))) AS difference;
