SELECT E.episode_id FROM Episode E JOIN Keyword K ON E.episode_id = K.episode_id WHERE K.keyword IN ('nun', 'priest') GROUP BY E.episode_id HAVING COUNT(DISTINCT K.keyword) = 2;
SELECT E.episode_id FROM Episode E JOIN Award A ON E.episode_id = A.episode_id WHERE E.rating = 8.5 AND A.award = 'Best Television Episode' AND A.result = 'Winner';
SELECT T1.title FROM Episode AS T1 INNER JOIN Vote AS T2 ON T1.episode_id = T2.episode_id WHERE T2.stars = 10 LIMIT 3
SELECT T2.value, T2.units FROM patients AS T1 INNER JOIN observations AS T2 ON T1.patient = T2.PATIENT WHERE T1.first = 'Elly' AND T1.last = 'Koss' AND T2.date = '2008-03-11' AND T2.description = 'Body Height'
SELECT weight_2009.VALUE - weight_2008.VALUE AS weight_increase FROM (SELECT VALUE FROM observations WHERE PATIENT IN (SELECT patient FROM patients WHERE first = 'Elly' AND last = 'Koss') AND DATE LIKE '2009%' AND DESCRIPTION = 'Body Weight') AS weight_2009, (SELECT VALUE FROM observations WHERE PATIENT IN (SELECT patient FROM patients WHERE first = 'Elly' AND last = 'Koss') AND DATE LIKE '2008%' AND DESCRIPTION = 'Body Weight') AS weight_2008;
SELECT MAX(T2.VALUE) FROM patients T1 JOIN observations T2 ON T1.patient = T2.PATIENT WHERE T1.first = 'Elly' AND T1.last = 'Koss' AND T2.DESCRIPTION = 'Systolic Blood Pressure';
