SELECT SUM(julianday(m.STOP) - julianday(m.START)) AS total_days FROM patients p JOIN medications m ON p.patient = m.PATIENT WHERE p.first = 'Elly' AND p.last = 'Koss' AND m.DESCRIPTION LIKE 'Acetaminophen%'
