SELECT (COUNT(DISTINCT CASE WHEN T1.marital = 'M' THEN T1.patient END) * 100.0 / COUNT(DISTINCT T1.patient)) AS percentage FROM patients T1 JOIN conditions T2 ON T1.patient = T2.PATIENT WHERE T2.DESCRIPTION = 'Cystitis';
