SELECT T2.gender FROM (SELECT gender, COUNT(*) AS count FROM patients T1 JOIN allergies T2 ON T1.patient = T2.PATIENT WHERE T2.DESCRIPTION = 'Dander (animal) allergy' GROUP BY gender) T2 ORDER BY T2.count DESC LIMIT 1;
