SELECT DISTINCT T3.`Product Name` FROM people AS T1 INNER JOIN central_superstore AS T2 ON T1.`Customer ID` = T2.`Customer ID` INNER JOIN product AS T3 ON T3.`Product ID` = T2.`Product ID` WHERE T1.`Customer Name` = 'Bill Shonely' AND T2.Region = 'Central'
SELECT DISTINCT T2.`Customer Name` FROM west_superstore AS T1 INNER JOIN people AS T2 ON T1.`Customer ID` = T2.`Customer ID` WHERE T1.Quantity = 8 AND T1.Region = 'West'
SELECT SUM(T2.Profit) AS Total_Profit FROM people T1 JOIN central_superstore T2 ON T1."Customer ID" = T2."Customer ID" AND T1.Region = T2.Region WHERE T1.City = 'Houston' AND T1.State = 'Texas' AND T1.Region = 'Central';
SELECT DISTINCT T2.`Customer Name` FROM east_superstore AS T1 INNER JOIN people AS T2 ON T1.`Customer ID` = T2.`Customer ID` WHERE T1.`Ship Date` = '2013-03-05'
SELECT T2.`Product Name` FROM central_superstore AS T1 INNER JOIN product AS T2 ON T1.`Product ID` = T2.`Product ID` WHERE T2.Region = 'Central' AND STRFTIME('%Y', T1.`Order Date`) = '2016' ORDER BY T1.Profit ASC LIMIT 1
SELECT DISTINCT T2.`Customer Name` FROM east_superstore AS T1 INNER JOIN people AS T2 ON T1.`Customer ID` = T2.`Customer ID` WHERE T1.`Order ID` = 'CA-2011-118976' AND T2.Region = 'East'
SELECT T2.`Product Name` FROM south_superstore AS T1 INNER JOIN product AS T2 ON T1.`Product ID` = T2.`Product ID` WHERE T2.Region = 'South' ORDER BY T1.Sales DESC LIMIT 1
SELECT T1.Sales, T1.Profit, T2.`Sub-Category` FROM east_superstore AS T1 INNER JOIN product AS T2 ON T1.`Product ID` = T2.`Product ID` WHERE T1.`Order ID` = 'US-2011-126571' AND T2.Region = 'East'
SELECT T2.`Product Name` FROM east_superstore AS T1 INNER JOIN product AS T2 ON T1.`Product ID` = T2.`Product ID` WHERE T2.Region = 'East' ORDER BY T1.Quantity DESC LIMIT 1
SELECT "Customer Name" FROM people WHERE ("Customer ID", Region) IN (SELECT "Customer ID", Region FROM south_superstore WHERE Region = 'South' AND "Ship Mode" = 'Standard Class' AND Sales > (SELECT AVG(Sales) * 0.88 FROM south_superstore));
SELECT CAST(SUM(CASE  WHEN T2.Discount = 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM people AS T1 INNER JOIN central_superstore AS T2 ON T1.`Customer ID` = T2.`Customer ID` WHERE T2.Region = 'Central' AND T1.State = 'Indiana'
SELECT CAST(SUM(IIF(race = 'W', 1, 0)) AS REAL) * 100 / COUNT(case_number) FROM officers WHERE gender = 'M'
SELECT CAST(SUM(IIF(officer_count > 3, 1, 0)) AS REAL) * 100 / COUNT(case_number) FROM incidents WHERE STRFTIME('%Y', date) BETWEEN '2010' AND '2015'
SELECT STRFTIME('%Y', date) FROM incidents WHERE subject_weapon = 'Handgun' GROUP BY STRFTIME('%Y', date) ORDER BY COUNT(case_number) DESC LIMIT 1
SELECT CAST(SUM(subject_statuses = 'Injured') AS REAL) * 100 / COUNT(case_number) FROM incidents WHERE grand_jury_disposition = 'No Bill'
SELECT (SELECT COUNT(*) FROM incidents WHERE subject_weapon = 'Vehicle' AND date LIKE '2008%') - (SELECT COUNT(*) FROM incidents WHERE subject_weapon = 'Vehicle' AND date LIKE '2007%') AS difference;
SELECT CAST(SUM(subject_statuses = 'Shoot and Miss') AS REAL) * 100 / COUNT(case_number) FROM incidents WHERE subject_weapon = 'Handgun'
SELECT T2.last_name, T2.gender FROM incidents AS T1 INNER JOIN officers AS T2 ON T1.case_number = T2.case_number WHERE T1.grand_jury_disposition = 'No Bill'
SELECT T1.case_number, T1.subject_statuses, T1.subject_weapon FROM incidents AS T1 INNER JOIN subjects AS T2 ON T1.case_number = T2.case_number WHERE T2.gender = 'F'
SELECT case_number, location, subject_statuses FROM incidents WHERE case_number IN (SELECT case_number FROM subjects WHERE gender = 'M');
SELECT T1.case_number, T1.grand_jury_disposition FROM incidents AS T1 INNER JOIN officers AS T2 ON T1.case_number = T2.case_number WHERE T2.first_name = 'George' AND T2.last_name = 'Evenden'
SELECT T2.last_name, T1.subject_statuses FROM incidents AS T1 INNER JOIN officers AS T2 ON T1.case_number = T2.case_number WHERE T1.case_number = '134472-2015'
SELECT T2.last_name, T2.gender, T2.race, T2.case_number FROM incidents AS T1 INNER JOIN subjects AS T2 ON T1.case_number = T2.case_number WHERE T1.subject_statuses = 'Deceased'
SELECT CAST(SUM(T1.subject_weapon = 'Vehicle') AS REAL) * 100 / COUNT(T1.case_number) FROM incidents T1 INNER JOIN subjects T2 ON T1.case_number = T2.case_number WHERE T2.gender = 'F'
SELECT (SELECT COUNT(*) FROM incidents WHERE subject_statuses LIKE '%Injured%' AND subject_weapon = 'Knife') * 1.0 / (SELECT COUNT(*) FROM incidents WHERE subject_statuses LIKE '%Injured%' AND subject_weapon = 'Handgun') AS ratio FROM incidents WHERE subject_statuses LIKE '%Injured%' LIMIT 1;
SELECT case_number FROM incidents WHERE date LIKE '2012%' AND subject_statuses = 'Deceased';
SELECT CAST(SUM(race = 'B') AS REAL) * 100 / COUNT(case_number) FROM officers WHERE gender = 'M'
SELECT COUNT(DISTINCT T1.case_number) FROM incidents T1, officers T2 WHERE T1.case_number = T2.case_number AND T1.subject_weapon = 'Vehicle' AND T2.gender = 'F';
SELECT COUNT(DISTINCT T1.case_number) FROM subjects T1 JOIN incidents T2 ON T1.case_number = T2.case_number WHERE T1.gender = 'F' AND T2.subject_statuses = 'Deceased';
SELECT COUNT(T1.case_number) FROM officers AS T1 INNER JOIN incidents AS T2 ON T2.case_number = T1.case_number WHERE T1.race = 'B' AND T2.date BETWEEN '2010-01-01' AND '2015-12-31'
SELECT COUNT(case_number) FROM incidents WHERE date BETWEEN '2015-06-01' AND '2015-06-30'
SELECT COUNT(location) FROM incidents WHERE subject_weapon = 'Handgun' AND subject_statuses = 'Injured' AND date BETWEEN '2006-01-01' AND '2013-12-31'
SELECT subject_weapon FROM incidents WHERE subject_statuses = 'Deceased' GROUP BY subject_weapon HAVING COUNT(subject_weapon) = (SELECT MAX(weapon_count) FROM (SELECT COUNT(subject_weapon) AS weapon_count FROM incidents WHERE subject_statuses = 'Deceased' GROUP BY subject_weapon) T);
SELECT (COUNT(*) FILTER (WHERE race = 'W' AND gender = 'M') * 100.0 / COUNT(*)) AS proportion_white_males, (COUNT(*) FILTER (WHERE race = 'W' AND gender = 'F') * 100.0 / COUNT(*)) AS proportion_white_females FROM officers;
SELECT (SELECT COUNT(*) FROM subjects WHERE race = 'B' AND gender = 'F') - (SELECT COUNT(*) FROM subjects WHERE race = 'W' AND gender = 'F') AS difference;
SELECT (COUNT(*) * 100.0 / (SELECT COUNT(*) FROM incidents WHERE subject_statuses = 'Deceased')) AS percentage FROM incidents WHERE subject_statuses = 'Deceased' AND subject_weapon = 'Rifle';
SELECT T1.subject_weapon, T2.race, T2.gender FROM incidents AS T1 INNER JOIN subjects AS T2 ON T1.case_number = T2.case_number WHERE T1.case_number = '031347-2015'
SELECT T3.race, T3.gender FROM officers T1 JOIN incidents T2 ON T1.case_number = T2.case_number JOIN subjects T3 ON T2.case_number = T3.case_number WHERE T1.full_name = 'Ruben Fredirick' AND T2.subject_statuses = 'Deceased Injured';
SELECT (COUNT(DISTINCT T1.case_number) * 100.0 / (SELECT COUNT(DISTINCT case_number) FROM incidents WHERE subject_statuses = 'Injured')) AS proportion FROM officers T1 JOIN incidents T2 ON T1.case_number = T2.case_number WHERE T1.gender = 'M' AND T2.subject_statuses = 'Injured';
SELECT Chromosome FROM Genes WHERE Localization = 'plasma membrane';
SELECT COUNT(*) FROM Genes WHERE Essential = 'Non-Essential' AND Localization = 'nucleus';
SELECT COUNT(T1.GeneID) FROM Genes AS T1 INNER JOIN Classification AS T2 ON T1.GeneID = T2.GeneID WHERE T2.Localization = 'vacuole' AND T1.Phenotype = 'Nucleic acid metabolism defects'
SELECT Localization FROM Genes WHERE Chromosome = (SELECT Chromosome FROM Genes GROUP BY Chromosome ORDER BY COUNT(*) DESC LIMIT 1)
SELECT T2.Expression_Corr FROM Genes AS T1 INNER JOIN Interactions AS T2 ON T1.GeneID = T2.GeneID1 INNER JOIN Genes AS T3 ON T3.GeneID = T2.GeneID2 WHERE T1.Localization = 'nucleus' AND T3.Localization = 'nucleus' ORDER BY T2.Expression_Corr DESC LIMIT 1
SELECT T1.Function FROM Genes AS T1 INNER JOIN Interactions AS T2 ON T1.GeneID = T2.GeneID1 ORDER BY T2.Expression_Corr ASC LIMIT 1
WITH NonMotorProteins AS (SELECT GeneID FROM Genes WHERE Class != 'Motorproteins') SELECT COUNT(*) FROM Interactions WHERE Expression_Corr < 0 AND GeneID1 IN (SELECT GeneID FROM NonMotorProteins) AND GeneID2 IN (SELECT GeneID FROM NonMotorProteins);
SELECT T2.Expression_Corr FROM Genes AS T1 INNER JOIN Interactions AS T2 ON T1.GeneID = T2.GeneID1 WHERE T1.Chromosome = 6 OR T1.Chromosome = 8 ORDER BY T2.Expression_Corr DESC LIMIT 1
SELECT Motif FROM Genes WHERE Localization = 'cytoplasm' AND Chromosome = 7;
SELECT COUNT(*) FROM Genes WHERE Essential = 'Non-Essential' AND Function LIKE 'transcription' AND NOT Localization = 'cytoplasm';
SELECT COUNT(T2.GeneID2) FROM Genes AS T1 INNER JOIN Interactions AS T2 ON T1.GeneID = T2.GeneID1 WHERE T2.Expression_Corr > 0 AND T1.Essential = 'Non-Essential'
SELECT COUNT(*) * 1.0 / (SELECT COUNT(*) FROM Interactions WHERE Expression_Corr > 0) FROM Interactions I JOIN Genes G1 ON I.GeneID1 = G1.GeneID JOIN Genes G2 ON I.GeneID2 = G2.GeneID WHERE I.Expression_Corr > 0 AND G1.Chromosome > 10 AND G2.Chromosome > 10;
SELECT AVG(I.Expression_Corr) FROM Interactions I JOIN Genes G1 ON I.GeneID1 = G1.GeneID JOIN Genes G2 ON I.GeneID2 = G2.GeneID WHERE G1.Class = 'ATPases' AND G2.Class = 'ATPases';
SELECT GeneID FROM Genes WHERE Localization LIKE 'cytoplasm' AND Function LIKE 'metabolism';
SELECT COUNT(DISTINCT GeneID) FROM Classification WHERE Localization LIKE 'plasma' OR Localization LIKE 'nucleus';
SELECT Expression_Corr FROM Interactions WHERE Type = 'Physical' UNION ALL SELECT CAST(SUM(Expression_Corr < 0) AS REAL) * 100 / COUNT(*) FROM Interactions WHERE Type = 'Physical'
SELECT SUM(Localization = 'cytoskeleton' AND Phenotype = 'Conditional phenotypes') , CAST(SUM(Localization = 'cytoskeleton') AS REAL) * 100 / COUNT(GeneID) FROM Genes;
SELECT DISTINCT T2.Type FROM Genes T1 JOIN Interactions T2 ON T1.GeneID = T2.GeneID1 WHERE T1.Essential = 'Non-Essential' AND T1.Function = 'cellular transport and transport medicine';
SELECT T1.GeneID FROM Genes AS T1 INNER JOIN Interactions AS T2 ON T1.GeneID = T2.GeneID1 WHERE T2.Expression_Corr > 0 AND T1.Localization = 'nucleus'
SELECT T2.GeneID1 FROM Genes AS T1 INNER JOIN Interactions AS T2 ON T1.GeneID = T2.GeneID1 WHERE T1.Localization = 'nucleus' AND T1.Class = 'Transcription factors' AND T1.Essential = 'Essential' AND T2.Expression_Corr != 0
SELECT COUNT(T1.GeneID) FROM Genes AS T1 INNER JOIN Interactions AS T2 ON T1.GeneID = T2.GeneID1 WHERE T2.Type != 'Physical' AND T1.Phenotype = 'Cell cycle defects' AND T1.Class != 'Motorproteins' AND T1.Essential = 'Non-Essential'
SELECT CAST(SUM(IIF(T2.Expression_Corr > 0, 1, 0)) AS REAL) * 100 / COUNT(T2.GeneID1) FROM Genes AS T1 INNER JOIN Interactions AS T2 ON T1.GeneID = T2.GeneID1 WHERE T1.Phenotype = 'Nucleic acid metabolism defects' AND T1.Motif = 'PS00107'
SELECT CAST(COUNT(T1.GeneID) AS REAL) * 100 / ( SELECT COUNT(T1.GeneID) FROM Genes AS T1 INNER JOIN Interactions AS T2 ON T1.GeneID = T2.GeneID1 WHERE T2.Expression_Corr < 0 ) FROM Genes AS T1 INNER JOIN Interactions AS T2 ON T1.GeneID = T2.GeneID1 WHERE T2.Expression_Corr < 0 AND T1.Essential = 'Non-Essential'
SELECT DISTINCT Translated_Review FROM user_reviews WHERE App IN ( SELECT App FROM playstore WHERE `Last Updated` BETWEEN 'January 1, 2018' AND 'January 31, 2018' ) AND Sentiment = 'Positive'
SELECT COUNT(T2.Sentiment_Polarity), T1."Last Updated" FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.App = '7 Minute Workout' AND T2.Sentiment_Polarity BETWEEN 0 AND 0.5
SELECT COUNT(*) AS NeutralCount, (SELECT Rating FROM playstore WHERE App = 'HTC Weather') AS Rating FROM user_reviews WHERE Sentiment = 'Neutral' AND App = 'HTC Weather';
SELECT DISTINCT T1.App, T1.Category FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T2.Sentiment_Polarity = '-1.0'
SELECT AVG(T2.Sentiment_Polarity), T1."Content Rating" FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.App = 'Cooking Fever'
SELECT MIN(T2.Sentiment_Polarity), T1.Installs FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.App = 'Basketball Stars'
SELECT COUNT(T2.Sentiment_Subjectivity), T1."Current Ver" FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.App = 'Akinator' AND T2.Sentiment_Subjectivity < 0.5
SELECT COUNT(App) FROM playstore WHERE Rating = 5
SELECT App FROM playstore WHERE Price = 0 ORDER BY CAST(REPLACE(REPLACE(Installs, ',', ''), '+', '') AS INTEGER) DESC LIMIT 5
SELECT DISTINCT App FROM playstore ORDER BY Reviews DESC LIMIT 10
SELECT COUNT(T1.App), T2.Category FROM user_reviews T1 JOIN playstore T2 ON T1.App = T2.App WHERE T1.Sentiment = 'Neutral' AND T1.App = '10 Best Foods for You' GROUP BY T2.Category;
SELECT DISTINCT T2.App, T2.Installs FROM playstore T2 INNER JOIN user_reviews T1 ON T2.App = T1.App WHERE T1.Sentiment = 'Positive';
SELECT T1.App, T2.Translated_Review FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.Rating = 3.9
SELECT DISTINCT Sentiment FROM user_reviews WHERE App IN ( SELECT App FROM playstore WHERE `Android Ver` = '8.0 and up' )
SELECT T1.App, SUM(CAST(T2.Sentiment_Subjectivity AS REAL)) AS Total_Sentiment_Subjectivity FROM (SELECT App FROM playstore GROUP BY App HAVING COUNT(DISTINCT Genres) > 1) T1 JOIN user_reviews T2 ON T1.App = T2.App GROUP BY T1.App;
SELECT DISTINCT App, Sentiment FROM user_reviews WHERE App IN ( SELECT App FROM playstore WHERE CAST(SUBSTR('Last Updated', -4, 4) AS INTEGER) < 2015 )
SELECT SUM(T1.Installs), T2.Translated_Review FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1."Content Rating" = 'Adults only 18+'
SELECT T1.App, T2.Sentiment_Polarity FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App ORDER BY T1.Price * CAST(REPLACE(REPLACE(Installs, ',', ''), '+', '') AS INTEGER) DESC LIMIT 1
SELECT AVG(T1.Rating) , COUNT(CASE WHEN T2.Sentiment = 'Positive' THEN 1 ELSE NULL END) FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.Category = 'COMICS'
SELECT Rating FROM playstore WHERE APP = 'Draw A Stickman'
SELECT COUNT(App) FROM user_reviews WHERE App = 'Brit + Co' AND Translated_Review IS NOT NULL
SELECT App FROM playstore WHERE Genres = 'Shopping' ORDER BY Reviews DESC LIMIT 5;
SELECT COUNT(App) FROM user_reviews WHERE App = 'Dino War: Rise of Beasts' AND Sentiment = 'Neutral'
SELECT App FROM playstore WHERE Installs = '5,000+';
SELECT Translated_Review FROM user_reviews WHERE App = 'Dog Run - Pet Dog Simulator' AND Sentiment = 'Negative'
SELECT App FROM (SELECT T1.App, COUNT(*) as NegativeCount FROM playstore T1 INNER JOIN user_reviews T2 ON T1.App = T2.App WHERE T1.Type = 'Free' AND T2.Sentiment = 'Negative' GROUP BY T1.App) WHERE NegativeCount = (SELECT MAX(NegativeCount) FROM (SELECT T1.App, COUNT(*) as NegativeCount FROM playstore T1 INNER JOIN user_reviews T2 ON T1.App = T2.App WHERE T1.Type = 'Free' AND T2.Sentiment = 'Negative' GROUP BY T1.App));
SELECT COUNT(*) FROM user_reviews WHERE App IN (SELECT App FROM playstore WHERE Installs = '100,000,000+') AND Sentiment = 'Negative';
SELECT DISTINCT T1.`Content Rating` FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T2.Translated_Review LIKE '%gr8%'
SELECT SUM(T2.Sentiment_Polarity) FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.Price = ( SELECT MAX(Price) FROM playstore )
SELECT T1.Rating, T2.Translated_Review FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.App = 'Garden Coloring Book'
SELECT T1.App FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.Genres = 'Photography' GROUP BY T1.App ORDER BY SUM(T2.Sentiment_Subjectivity) DESC LIMIT 1
SELECT T2.Translated_Review FROM playstore T1 JOIN user_reviews T2 ON T1.App = T2.App WHERE T1.Rating = 1 AND T1."Content Rating" = 'Mature 17+';
SELECT Installs FROM playstore WHERE App = (SELECT App FROM user_reviews GROUP BY App ORDER BY SUM(CAST(Sentiment_Polarity AS REAL)) DESC LIMIT 1);
SELECT COUNT(T2.Sentiment) FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.Genres = 'Weather' AND T2.Sentiment = 'Neutral'
SELECT T1.App FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.Installs = '1,000,000+' AND T2.Translated_Review = 'nan' GROUP BY T1.App ORDER BY COUNT(T2.Translated_Review) DESC LIMIT 1
SELECT Rating, (SELECT SUM(Sentiment_Subjectivity) FROM user_reviews WHERE App = 'Onefootball - Soccer Scores' AND Sentiment_Subjectivity IS NOT NULL) AS TotalSentimentSubjectivity FROM playstore WHERE App = 'Onefootball - Soccer Scores';
SELECT CAST(COUNT(CASE WHEN T1.`Content Rating` = 'Teen' THEN 1 ELSE NULL END) AS REAL) * 100 / COUNT(T1.App) FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T2.Translated_Review = 'nan'
SELECT DISTINCT App FROM playstore WHERE Rating = 5
SELECT DISTINCT App FROM playstore WHERE Reviews > 75000000 AND `Content Rating` = 'Teen'
SELECT Genres FROM playstore WHERE Installs = '1,000,000,000+' GROUP BY Genres
SELECT AVG(Price) FROM playstore WHERE Genres = 'Dating'
SELECT AVG(CAST(REPLACE(REPLACE(Installs, ',', ''), '+', '') AS INTEGER)) FROM playstore WHERE Category = 'ENTERTAINMENT' AND Size < '1.0M'
SELECT AVG(Reviews) FROM playstore WHERE Rating = 5
SELECT Genres FROM playstore WHERE App IN ( SELECT App FROM user_reviews WHERE Sentiment = 'Positive' AND Sentiment_Polarity > 0.5 ORDER BY Sentiment_Polarity DESC LIMIT 3 )
SELECT (COUNT(*) * 100.0 / (SELECT COUNT(*) FROM playstore WHERE Rating = 4.7)) AS percentage FROM (SELECT T1.App FROM playstore T1 JOIN user_reviews T2 ON T1.App = T2.App WHERE T1.Rating = 4.7 GROUP BY T1.App HAVING SUM(CASE WHEN T2.Sentiment = 'Positive' THEN 1 ELSE 0 END) > SUM(CASE WHEN T2.Sentiment = 'Negative' THEN 1 ELSE 0 END))
SELECT T1.App, AVG(T1.Rating) AS AverageRating FROM playstore T1 WHERE T1.App NOT IN (SELECT T2.App FROM user_reviews T2 WHERE T2.Sentiment = 'Negative') GROUP BY T1.App
SELECT CAST((( SELECT COUNT(*) Po FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE SUBSTR(T1."Last Updated", -4, 4) > '2015' AND T2.Sentiment = 'Positive' ) - ( SELECT COUNT(*) Ne FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE SUBSTR(T1."Last Updated", -4, 4) > '2015' AND T2.Sentiment = 'Negative' )) AS REAL) * 100 / ( SELECT COUNT(*) NUM FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE SUBSTR(T1."Last Updated", -4, 4) > '2015' )
SELECT (COUNT(*) * 100.0 / (SELECT COUNT(*) FROM playstore WHERE Type = 'Free')) AS percentage FROM playstore WHERE Type = 'Free' AND Rating >= 4.5;
SELECT DISTINCT Genres FROM playstore WHERE App = 'Honkai Impact 3rd'
SELECT DISTINCT Rating FROM playstore WHERE App = 'Learn C++'
SELECT AVG(Price) FROM playstore WHERE 'Content Rating' = 'Everyone 10+' AND Genres = 'Arcade'
SELECT T1.Size, (SELECT COUNT(*) FROM user_reviews WHERE App = 'Browser 4G' AND Sentiment_Polarity = '0.5') FROM playstore T1 WHERE T1.App = 'Browser 4G'
SELECT T1.App, T2.Installs FROM user_reviews T1 JOIN playstore T2 ON T1.App = T2.App WHERE T1.Sentiment_Subjectivity = '0.3';
SELECT (SELECT AVG(CAST(Sentiment_Polarity AS REAL)) FROM user_reviews WHERE App = 'Golf GPS Rangefinder: Golf Pad') AS Average_Polarity, (SELECT Rating FROM playstore WHERE App = 'Golf GPS Rangefinder: Golf Pad') AS App_Rating;
SELECT p.App, COUNT(u.Sentiment) AS NegativeCount FROM playstore p LEFT JOIN user_reviews u ON p.App = u.App WHERE p.Genres LIKE 'Puzzle' AND u.Sentiment = 'Negative' GROUP BY p.App ORDER BY p.Rating ASC LIMIT 5
SELECT CAST(SUM(CASE WHEN T2.Sentiment = 'Positive' THEN 1 ELSE 0 END) AS REAL) * 100 / SUM(CASE WHEN T2.Sentiment = 'Negative' THEN 1 ELSE 0 END), T1.`Current Ver` FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.App = 'Fate/Grand Order (English)' AND T1.`Current Ver` = '1.18.0'
SELECT T1.Installs, (CAST(SUM(CASE WHEN T2.Sentiment = 'Positive' THEN 1 ELSE 0 END) AS FLOAT) / COUNT(T2.Sentiment) * 100) AS PositiveSentimentPercentage FROM playstore T1 JOIN user_reviews T2 ON T1.App = T2.App WHERE T1.App = 'FREEDOME VPN Unlimited anonymous Wifi Security' GROUP BY T1.Installs;
SELECT MAX(T1.Sentiment_Polarity) AS MaxPolarity, T2.Genres FROM user_reviews T1 JOIN playstore T2 ON T1.App = T2.App WHERE T1.App = 'Honkai Impact 3rd' GROUP BY T2.Genres
SELECT p.Rating, COUNT(u.Sentiment_Polarity) AS Dislike_Count FROM playstore p LEFT OUTER JOIN user_reviews u ON p.App = u.App AND u.Sentiment_Polarity < -0.5 WHERE p.App = 'Dragon Ball Legends'
SELECT T1.App, T2.Translated_Review FROM playstore T1 LEFT JOIN user_reviews T2 ON T1.App = T2.App WHERE T1.Category = 'EDUCATION' AND T1.Rating = 1;
SELECT T1.App, T2.Translated_Review FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.Type = 'Free' AND T1.Category = 'SPORTS'
SELECT COUNT(DISTINCT T1.App), AVG(CAST(T2.Sentiment_Polarity AS REAL)) FROM playstore T1 LEFT JOIN user_reviews T2 ON T1.App = T2.App WHERE T1.Genres = 'Role Playing' AND T1."Content Rating" = 'Teen'
SELECT AVG(T1.Rating), CAST(COUNT(CASE WHEN T2.Sentiment = 'Positive' THEN 1 ELSE NULL END) AS REAL) * 100 / COUNT(T2.Sentiment) FROM playstore AS T1 INNER JOIN user_reviews AS T2 ON T1.App = T2.App WHERE T1.Genres = 'Racing'
SELECT Region FROM `Sales Team` GROUP BY Region ORDER BY COUNT(DISTINCT `Sales Team`) DESC LIMIT 1
SELECT T FROM ( SELECT IIF(`Customer Names` LIKE '%Group%', `Customer Names`, NULL) AS T FROM Customers ) WHERE T IS NOT NULL
SELECT AVG(`Median Income`) FROM `Store Locations` WHERE Type = 'City'
SELECT T2.`Sales Team`, T2.Region FROM `Sales Orders` AS T1 INNER JOIN `Sales Team` AS T2 ON T2.SalesTeamID = T1._SalesTeamID WHERE T1.OrderNumber = 'SO - 000137'
SELECT DISTINCT T1.ProductID, T1.`Product Name` FROM Products AS T1 INNER JOIN `Sales Orders` AS T2 ON T2._ProductID = T1.ProductID INNER JOIN `Sales Team` AS T3 ON T3.SalesTeamID = T2._SalesTeamID WHERE T3.`Sales Team` = 'Douglas Tucker'
SELECT DISTINCT T1.`Customer Names` FROM Customers AS T1 INNER JOIN `Sales Orders` AS T2 ON T2._CustomerID = T1.CustomerID INNER JOIN Products AS T3 ON T3.ProductID = T2._ProductID WHERE T3.`Product Name` = 'Cocktail Glasses' AND SUBSTR(T2.OrderDate, -2) = '20' AND T2.`Discount Applied` = ( SELECT T2.`Discount Applied` FROM Customers AS T1 INNER JOIN `Sales Orders` AS T2 ON T2._CustomerID = T1.CustomerID INNER JOIN Products AS T3 ON T3.ProductID = T2._ProductID WHERE T3.`Product Name` = 'Cocktail Glasses' AND T2.OrderDate LIKE '%/%/20' ORDER BY T2.`Discount Applied` DESC LIMIT 1 )
SELECT DISTINCT T1.OrderNumber, T2.`City Name` FROM `Sales Orders` AS T1 INNER JOIN `Store Locations` AS T2 ON T2.StoreID = T1._StoreID WHERE T1.`Sales Channel` = 'In-Store'
SELECT T2.OrderNumber, T1.`Customer Names`, T2.OrderDate FROM Customers AS T1 INNER JOIN `Sales Orders` AS T2 ON T2._CustomerID = T1.CustomerID INNER JOIN Products AS T3 ON T3.ProductID = T2._ProductID ORDER BY T2.`Unit Cost` DESC LIMIT 1
SELECT DISTINCT T FROM ( SELECT CASE  WHEN T1.OrderDate LIKE '%/%/18' AND T2.`Customer Names` = 'Rochester Ltd' THEN T1.OrderNumber ELSE NULL END AS T FROM `Sales Orders` T1 INNER JOIN Customers T2 ON T2.CustomerID = T1._CustomerID ) WHERE T IS NOT NULL
SELECT DISTINCT T1.`Product Name`, T3.`Sales Team` FROM Products AS T1 INNER JOIN `Sales Orders` AS T2 ON T2._ProductID = T1.ProductID INNER JOIN `Sales Team` AS T3 ON T3.SalesTeamID = T2._SalesTeamID WHERE T2.WarehouseCode = 'WARE-NMK1003'
