SELECT AVG(CAST(T1.weight AS REAL) / (T1.height * T1.height)) FROM players AS T1 INNER JOIN player_allstar AS T2 ON T1.playerID = T2.playerID
SELECT name FROM teams WHERE tmID IN (SELECT tmID FROM teams WHERE year = 1973 AND lgID = 'ABA' AND (won * 1.0 / (won + lost)) = (SELECT MAX(T2.won * 1.0 / (T2.won + T2.lost) - T1.won * 1.0 / (T1.won + T1.lost)) FROM teams T1 JOIN teams T2 ON T1.tmID = T2.tmID WHERE T1.year = 1972 AND T2.year = 1973 AND T1.lgID = 'ABA')) AND year = 1973;
SELECT firstName FROM players WHERE playerID IN (SELECT playerID FROM players_teams WHERE lgID = 'NBL' AND PF IS NOT NULL GROUP BY playerID HAVING SUM(PF) = (SELECT MAX(totalPF) FROM (SELECT SUM(PF) AS totalPF FROM players_teams WHERE lgID = 'NBL' AND PF IS NOT NULL GROUP BY playerID)))
SELECT AVG(height) AS average_height FROM players WHERE playerID IN (SELECT playerID FROM player_allstar WHERE conference = 'East') AND height IS NOT NULL;
