SELECT T2.firstName || ' ' || T2.middleName || ' ' || T2.lastName AS fullName, (2003 - strftime('%Y', T2.birthDate)) AS age FROM awards_players T1 JOIN players T2 ON T1.playerID = T2.playerID WHERE T1.award = 'Finals MVP' AND T1.year = 2003;
