SELECT name, coachID FROM teams JOIN (SELECT tmIDWinner AS tmID, year FROM series_post WHERE round = 'QF' AND year = 1946 UNION SELECT tmIDLoser AS tmID, year FROM series_post WHERE round = 'QF' AND year = 1946) AS QualifiedTeams ON teams.tmID = QualifiedTeams.tmID AND teams.year = QualifiedTeams.year JOIN coaches ON teams.tmID = coaches.tmID AND teams.year = coaches.year
