SELECT (COUNT(DISTINCT T1.playerID) * 100.0 / (SELECT COUNT(*) FROM players WHERE college = 'Auburn')) AS percentage FROM players T1 JOIN awards_players T2 ON T1.playerID = T2.playerID WHERE T1.college = 'Auburn' AND T2.award = 'All-Defensive Second Team';
SELECT DISTINCT T1.firstName, T1.middleName, T1.lastName FROM players AS T1 INNER JOIN player_allstar AS T2 ON T1.playerID = T2.playerID WHERE T2.season_id = 1997 ORDER BY T2.steals DESC LIMIT 5
