SELECT T3.firstName, T3.lastName FROM (SELECT T1.playerID, SUM(T2.points) AS total_points FROM draft T1 JOIN player_allstar T2 ON T1.playerID = T2.playerID WHERE T1.lgID = 'NBA' AND T1.draftYear BETWEEN 1990 AND 2000 GROUP BY T1.playerID) AS T4 JOIN players T3 ON T4.playerID = T3.playerID ORDER BY T4.total_points DESC LIMIT 1;
SELECT T1.firstName, T1.middleName, T1.lastName FROM players AS T1 INNER JOIN player_allstar AS T2 ON T1.playerID = T2.playerID WHERE T1.college = 'Wake Forest' AND T2.o_rebounds > T2.d_rebounds
