SELECT name FROM teams WHERE tmID IN (SELECT tmID FROM teams WHERE year BETWEEN 1980 AND 2000 AND rank = 1 GROUP BY tmID HAVING COUNT(*) >= 5) AND tmID IN (SELECT tmIDLoser FROM series_post WHERE year BETWEEN 1980 AND 2000 GROUP BY tmIDLoser HAVING COUNT(*) >= 2);
SELECT tmID FROM players_teams WHERE lgID = 'NBA' AND year BETWEEN 1991 AND 2000 AND minutes > 0 GROUP BY tmID ORDER BY MAX(CAST(points AS REAL) / minutes) DESC LIMIT 1;
SELECT (SELECT AVG(1970 - strftime('%Y', birthDate)) FROM players WHERE playerID IN (SELECT playerID FROM draft WHERE draftYear = 1970 AND lgID = 'ABA')) - (SELECT AVG(1970 - strftime('%Y', birthDate)) FROM players WHERE playerID IN (SELECT playerID FROM draft WHERE draftYear = 1970 AND lgID = 'NBA')) AS AgeDifference;
SELECT T1.playerID FROM players_teams T1 WHERE T1.year = 2011 AND T1.lgID = 'NBA' AND T1.GP = (SELECT MAX(T2.GP) FROM players_teams T2 WHERE T2.year = 2011 AND T2.lgID = 'NBA')
SELECT COUNT(DISTINCT T1.playerID) FROM draft T1 JOIN player_allstar T2 ON T1.playerID = T2.playerID WHERE T1.draftYear = 1996 AND T1.draftRound = 1 AND T1.lgID = 'NBA';
SELECT T2.tmID FROM awards_players T1 JOIN players_teams T2 ON T1.playerID = T2.playerID AND T1.year = T2.year WHERE T1.award LIKE '%MVP%' AND T1.year = 1997 AND T1.lgID = 'NBA';
SELECT won FROM teams WHERE year = 2001 AND lgID = 'NBA' AND tmID = (SELECT tmID FROM players_teams WHERE year = 2001 AND lgID = 'NBA' GROUP BY tmID ORDER BY SUM(points) DESC LIMIT 1);
SELECT AVG(T2.turnovers) AS turnovers_per_game FROM player_allstar T1 JOIN players_teams T2 ON T1.playerID = T2.playerID WHERE T1.season_id = 2003 AND T2.year = 2003 AND T2.lgID = 'NBA' AND T1.playerID = (SELECT playerID FROM player_allstar WHERE season_id = 2003 ORDER BY assists DESC LIMIT 1) AND T2.turnovers IS NOT NULL
SELECT COUNT(T1.playerID) FROM player_allstar AS T1 INNER JOIN awards_players AS T2 ON T1.playerID = T2.playerID WHERE first_name = 'Ray' AND last_name = 'Allen'
SELECT (CAST(T2.won AS FLOAT) / (T2.won + T2.lost)) - (CAST(T1.won AS FLOAT) / (T1.won + T1.lost)) AS win_rate_increase FROM draft D JOIN teams T1 ON D.tmID = T1.tmID AND T1.year = 2003 JOIN teams T2 ON D.tmID = T2.tmID AND T2.year = 2004 WHERE D.draftYear = 2003 AND D.draftOverall = 1;
SELECT COUNT(T1.id) FROM awards_coaches AS T1 INNER JOIN teams AS T2 ON T1.year = T2.year WHERE T1.year BETWEEN 1971 AND 1975 AND T1.award = 'NBA Coach of the Year' AND T2.tmID = 'POR'
SELECT CAST(SUM(IIF(T2.steals IS NOT NULL AND T1.tmID = 'LAL', 1, 0)) AS REAL) * 100 / COUNT(T1.tmID) FROM teams AS T1 INNER JOIN players_teams AS T2 ON T1.tmID = T2.tmID AND T1.year = T2.year
SELECT P.firstName, P.middleName, P.lastName FROM players P WHERE P.playerID IN (SELECT PT.playerID FROM players_teams PT LEFT JOIN teams T ON PT.tmID = T.tmID AND PT.year = T.year WHERE PT.year = 1996 AND T.playoff IS NULL GROUP BY PT.playerID ORDER BY MAX(PT.steals) DESC LIMIT 1)
SELECT T2.playerID FROM players_teams AS T1 INNER JOIN players AS T2 ON T1.playerID = T2.playerID WHERE T1.PostGP = 0 AND T1.year = 1988 ORDER BY T1.turnovers DESC LIMIT 1
SELECT tmID FROM teams WHERE year = 2000 AND lgID = 'NBA' AND playoff IS NULL AND won > 0 AND lost > 0 ORDER BY (won * 1.0 / (won + lost)) DESC LIMIT 1;
SELECT T2.tmID FROM players_teams AS T1 INNER JOIN teams AS T2 ON T1.tmID = T2.tmID AND T1.year = T2.year WHERE T1.year = 1998 AND T1.PostGP = 0 ORDER BY T1.points DESC LIMIT 1
SELECT T1.name FROM teams T1 WHERE T1.year = 2001 AND T1.tmID NOT IN (SELECT T2.tmID FROM players_teams T2 WHERE T2.year = 2001 AND T2.PostGP > 0) ORDER BY T1.won DESC LIMIT 1;
SELECT T2.tmID FROM players_teams AS T1 INNER JOIN teams AS T2 ON T1.tmID = T2.tmID AND T1.year = T2.year WHERE T1.PostGP = 0 AND T1.year = 1997 ORDER BY T1.rebounds DESC LIMIT 1
