WITH CategoryID AS (SELECT category_id FROM Categories WHERE category_name = 'Hotels & Travel'), BusinessInCategory AS (SELECT business_id FROM Business_Categories WHERE category_id = (SELECT category_id FROM CategoryID)), ReviewStats AS (SELECT business_id, COUNT(*) AS review_count, AVG(review_stars) AS avg_stars FROM Reviews WHERE business_id IN (SELECT business_id FROM BusinessInCategory) GROUP BY business_id), MaxReview AS (SELECT MAX(review_count) AS max_review FROM ReviewStats) SELECT business_id, (SUM((review_stars - (SELECT avg_stars FROM ReviewStats WHERE business_id = Reviews.business_id)) * (review_stars - (SELECT avg_stars FROM ReviewStats WHERE business_id = Reviews.business_id))) / COUNT(review_stars)) AS std_dev FROM Reviews WHERE business_id IN (SELECT business_id FROM ReviewStats WHERE review_count = (SELECT max_review FROM MaxReview)) GROUP BY business_id;
