SELECT (COUNT(DISTINCT T1.paper_id) * 100.0 / (SELECT COUNT(DISTINCT cited_paper_id) FROM cites)) AS percentage FROM paper AS T1 WHERE T1.class_label = 'Agents' AND T1.paper_id IN (SELECT cited_paper_id FROM cites);
WITH CitationCounts AS (SELECT word_cited_id, COUNT(paper_id) AS citation_count FROM content GROUP BY word_cited_id) SELECT word_cited_id, citation_count FROM CitationCounts WHERE citation_count = (SELECT MAX(citation_count) FROM CitationCounts);
SELECT COUNT(DISTINCT T2.word_cited_id) FROM paper AS T1 INNER JOIN content AS T2 ON T1.paper_id = T2.paper_id WHERE T1.class_label = 'AI'
SELECT DISTINCT T2.paper_id, T3.class_label FROM content T1 JOIN content T2 ON T1.word_cited_id = T2.word_cited_id JOIN paper T3 ON T2.paper_id = T3.paper_id WHERE T1.paper_id = '315017' AND T2.paper_id != '315017';
SELECT word_cited_id FROM content INNER JOIN paper ON content.paper_id = paper.paper_id WHERE paper.class_label = 'DB' GROUP BY word_cited_id HAVING COUNT(*) = (SELECT MAX(c) FROM (SELECT COUNT(*) AS c FROM content JOIN paper ON content.paper_id = paper.paper_id WHERE paper.class_label = 'DB' GROUP BY word_cited_id));
SELECT CAST(COUNT(DISTINCT CASE WHEN T1.class_label = 'Agents' THEN T2.word_cited_id ELSE NULL END) AS REAL) * 100 / COUNT(DISTINCT T2.word_cited_id) FROM paper AS T1 INNER JOIN content AS T2 ON T1.paper_id = T2.paper_id
SELECT T1.paper_id, T1.class_label FROM paper AS T1 INNER JOIN content AS T2 ON T1.paper_id = T2.paper_id GROUP BY T1.paper_id, T1.class_label ORDER BY COUNT(T2.word_cited_id) DESC LIMIT 1
SELECT T1.paper_id, T1.class_label FROM paper AS T1 INNER JOIN content AS T2 ON T1.paper_id = T2.paper_id WHERE T2.word_cited_id = 'word1002'
SELECT DISTINCT T2.word_cited_id FROM paper AS T1 INNER JOIN content AS T2 ON T1.paper_id = T2.paper_id WHERE T1.class_label = 'AI'
SELECT class_label, (SELECT COUNT(DISTINCT word_cited_id) FROM content WHERE paper_id = 'chakrabarti01integrating') AS cited_word_count FROM paper WHERE paper_id = 'chakrabarti01integrating';
SELECT DISTINCT T1.paper_id, T1.class_label FROM paper AS T1 INNER JOIN content AS T2 ON T1.paper_id = T2.paper_id GROUP BY T2.paper_id, T1.class_label HAVING COUNT(T2.word_cited_id) > 20
SELECT DISTINCT T2.word_cited_id FROM content T2 JOIN paper T1 ON T2.paper_id = T1.paper_id WHERE T1.class_label = 'AI' INTERSECT SELECT DISTINCT T2.word_cited_id FROM content T2 JOIN paper T1 ON T2.paper_id = T1.paper_id WHERE T1.class_label = 'IR';
WITH CitationCounts AS (SELECT cited_paper_id, COUNT(*) AS citation_count FROM cites GROUP BY cited_paper_id) SELECT cited_paper_id, citation_count FROM CitationCounts WHERE citation_count = (SELECT MAX(citation_count) FROM CitationCounts) UNION ALL SELECT cited_paper_id, citation_count FROM CitationCounts WHERE citation_count = (SELECT MIN(citation_count) FROM CitationCounts);
SELECT CAST(COUNT(CASE WHEN class_label = 'ML' THEN paper_id ELSE NULL END) AS REAL) / COUNT(paper_id) FROM paper
SELECT DISTINCT T2.word_cited_id FROM cites AS T1 INNER JOIN content AS T2 ON T1.cited_paper_id = T2.paper_id WHERE T1.citing_paper_id = 'sima01computational'
SELECT COUNT(T2.paper_id) FROM cites AS T1 INNER JOIN content AS T2 ON T1.cited_paper_id = T2.paper_id WHERE T1.citing_paper_id = 'schmidt99advanced' AND T2.word_cited_id = 'word3555'
SELECT DISTINCT T1.class_label FROM paper AS T1 INNER JOIN content AS T2 ON T1.paper_id = T2.paper_id WHERE T2.word_cited_id = 'word1163'
SELECT T1.paper_id FROM paper T1, content T2 WHERE T1.paper_id = T2.paper_id AND T1.class_label = 'DB' GROUP BY T1.paper_id HAVING COUNT(T2.word_cited_id) = (SELECT MAX(word_count) FROM (SELECT COUNT(word_cited_id) AS word_count FROM content GROUP BY paper_id) T3);
SELECT COUNT(T1.paper_id) FROM paper AS T1 INNER JOIN cites AS T2 ON T1.paper_id = T2.citing_paper_id WHERE T1.class_label = 'ML' AND T2.cited_paper_id = 'butz01algorithmic'
