SELECT full_name FROM person WHERE id IN (SELECT person_id FROM games_competitor WHERE age = (SELECT MAX(age) FROM games_competitor));
WITH CountedGames AS (SELECT games_id, COUNT(person_id) AS count FROM games_competitor JOIN person ON games_competitor.person_id = person.id WHERE person.gender = 'F' GROUP BY games_id) SELECT games_year FROM games JOIN CountedGames ON games.id = CountedGames.games_id WHERE CountedGames.count = (SELECT MAX(count) FROM CountedGames);
SELECT COUNT(DISTINCT T1.id) FROM person T1 JOIN person_region T2 ON T1.id = T2.person_id JOIN noc_region T3 ON T2.region_id = T3.id JOIN games_competitor T4 ON T1.id = T4.person_id WHERE T1.gender = 'M' AND T3.region_name = 'Belgium';
