SELECT (100.0 * COUNT(DISTINCT CASE WHEN T4.gender = 'F' THEN T4.id END) / COUNT(DISTINCT T4.id)) AS percentage FROM person T4 JOIN games_competitor T3 ON T4.id = T3.person_id JOIN competitor_event T2 ON T3.id = T2.competitor_id JOIN event T1 ON T2.event_id = T1.id WHERE T1.event_name = 'Equestrianism Mixed Three-Day Event, Individual'
SELECT AVG(T2.age) FROM games AS T1 INNER JOIN games_competitor AS T2 ON T1.id = T2.games_id INNER JOIN person AS T3 ON T2.person_id = T3.id WHERE T1.games_name = '1992 Summer'
SELECT games_year FROM games GROUP BY games_year HAVING SUM(CASE WHEN season = 'Summer' THEN 1 ELSE 0 END) = 1 AND SUM(CASE WHEN season = 'Winter' THEN 1 ELSE 0 END) = 0;
