SELECT COUNT(*) FROM competitor_event AS T1 JOIN event AS T2 ON T1.event_id = T2.id JOIN medal AS T3 ON T1.medal_id = T3.id WHERE T2.event_name = 'Ice Hockey Men''s Ice Hockey' AND T3.medal_name = 'Gold' AND T1.medal_id = 1;
WITH RegionMedals AS (SELECT T4.region_name, COUNT(T1.medal_id) AS medal_count FROM competitor_event T1 INNER JOIN games_competitor T2 ON T1.competitor_id = T2.id INNER JOIN person_region T3 ON T2.person_id = T3.person_id INNER JOIN noc_region T4 ON T3.region_id = T4.id WHERE T1.medal_id IS NOT NULL AND T1.medal_id <> 4 GROUP BY T4.region_name) SELECT region_name FROM RegionMedals WHERE medal_count = (SELECT MAX(medal_count) FROM RegionMedals)
SELECT DISTINCT P.full_name FROM person P, games_competitor GC, competitor_event CE, event E, sport S, medal M WHERE P.id = GC.person_id AND GC.id = CE.competitor_id AND CE.event_id = E.id AND E.sport_id = S.id AND CE.medal_id = M.id AND S.sport_name = 'Cycling' AND M.medal_name = 'Gold';
SELECT DISTINCT T1.medal_name FROM medal AS T1 INNER JOIN competitor_event AS T2 ON T1.id = T2.medal_id INNER JOIN games_competitor AS T3 ON T2.competitor_id = T3.id INNER JOIN person AS T4 ON T3.person_id = T4.id WHERE T4.full_name = 'Lee Chong Wei' AND T2.medal_id <> 4
