SELECT COUNT(DISTINCT T1.coachID) FROM AwardsCoaches T1 JOIN Master T2 ON T1.coachID = T2.coachID WHERE T1.year > 1940 AND T2.deathYear IS NOT NULL;
SELECT award FROM AwardsCoaches WHERE coachID IN (SELECT coachID FROM Coaches WHERE lgID = 'NHL') AND coachID IN (SELECT coachID FROM Master WHERE deathYear IS NOT NULL);
