SELECT birthYear FROM (SELECT T2.birthYear, COUNT(T1.award) AS TotalAwards FROM AwardsPlayers T1 JOIN Master T2 ON T1.playerID = T2.playerID GROUP BY T2.birthYear) WHERE TotalAwards = (SELECT MAX(TotalAwards) FROM (SELECT COUNT(T1.award) AS TotalAwards FROM AwardsPlayers T1 JOIN Master T2 ON T1.playerID = T2.playerID GROUP BY T2.birthYear));
SELECT T1.birthCountry FROM Master AS T1 INNER JOIN AwardsPlayers AS T2 ON T1.playerID = T2.playerID GROUP BY T1.birthCountry ORDER BY COUNT(T2.award) DESC LIMIT 1
SELECT T1.birthCountry FROM Master AS T1 INNER JOIN HOF AS T2 ON T1.hofID = T2.hofID GROUP BY T1.birthCountry ORDER BY COUNT(T1.playerID) DESC LIMIT 1
SELECT DISTINCT T2.pos FROM Master T1 JOIN AwardsPlayers T2 ON T1.playerID = T2.playerID WHERE T1.birthCountry = 'Canada' AND T2.award = 'All-Rookie';
SELECT AVG(CAST(weight AS REAL) / (CAST(height AS REAL) * CAST(height AS REAL))) AS average_BMI FROM Master M INNER JOIN HOF H ON M.hofID = H.hofID WHERE M.coachID IS NOT NULL AND M.weight IS NOT NULL AND M.height IS NOT NULL;
SELECT (COUNT(T2.hofID) * 100.0 / COUNT(T1.hofID)) AS percentage_of_american_players FROM HOF T1 LEFT JOIN Master T2 ON T1.hofID = T2.hofID AND T2.birthCountry = 'USA';
