SELECT TOTAL(Coaches.w) FROM Coaches JOIN AwardsCoaches ON Coaches.coachID = AwardsCoaches.coachID WHERE AwardsCoaches.award = 'Second Team All-Star' AND AwardsCoaches.year = 1933 AND Coaches.year = 1933;
