SELECT M.birthCountry || '-' || M.birthState || '-' || M.birthCity AS birthPlace FROM Coaches C JOIN Master M ON C.coachID = M.coachID WHERE C.notes = 'co-coach with Dave Lewis' AND C.year = 1998;
SELECT T2.firstName || ' ' || T2.lastName AS fullName FROM Goalies T1 JOIN Master T2 ON T1.playerID = T2.playerID WHERE T1.stint = 3 AND T2.weight = (SELECT MAX(weight) FROM Master WHERE playerID IN (SELECT playerID FROM Goalies WHERE stint = 3))
SELECT T2.firstName || ' ' || T2.lastName AS fullName FROM Goalies T1 JOIN Master T2 ON T1.playerID = T2.playerID WHERE T1.ENG = '10' ORDER BY T2.height DESC LIMIT 1;
SELECT T1.shootCatch FROM Master AS T1 INNER JOIN Goalies AS T2 ON T1.playerID = T2.playerID WHERE T2.year = 2010 GROUP BY T2.playerID ORDER BY SUM(T2.SHO) DESC LIMIT 1
