SELECT T2.name FROM Goalies AS T1 INNER JOIN Teams AS T2 ON T1.tmID = T2.tmID WHERE T1.year = 2010 GROUP BY T2.name ORDER BY SUM(PostENG) DESC LIMIT 1
SELECT MAX(T2.Pts) FROM Goalies T1 INNER JOIN Teams T2 ON T1.tmID = T2.tmID AND T1.year = T2.year WHERE T1.year = 1995 GROUP BY T1.tmID ORDER BY T1.PostSHO DESC LIMIT 1
WITH WinningRates AS (SELECT coachID, CAST(w AS REAL) / (w + l) AS rate FROM Coaches WHERE year = 2009 AND w IS NOT NULL AND l IS NOT NULL) SELECT M.nameNick FROM WinningRates WR JOIN Master M ON WR.coachID = M.coachID WHERE WR.rate = (SELECT MAX(rate) FROM WinningRates);
SELECT M.firstName || ' ' || M.lastName AS fullName FROM (SELECT T.tmID FROM TeamsPost T WHERE T.year = 2011 AND T.PPG IS NOT NULL AND T.PPC IS NOT NULL ORDER BY CAST(T.PPG AS FLOAT) / CAST(T.PPC AS FLOAT) DESC LIMIT 1) AS MaxTeam JOIN Coaches C ON MaxTeam.tmID = C.tmID AND C.year = 2011 JOIN Master M ON C.coachID = M.coachID;
