SELECT M.firstName || ' ' || M.lastName AS coachName FROM Teams T1 JOIN Coaches T2 ON T1.tmID = T2.tmID AND T1.year = T2.year JOIN Master M ON T2.coachID = M.coachID WHERE T1.year = 2003 AND T1.BenchMinor = (SELECT MAX(BenchMinor) FROM Teams WHERE year = 2003);
SELECT T1.playerID FROM Master T1 JOIN Goalies T2 ON T1.playerID = T2.playerID WHERE T2.year = 1978 AND CAST(T1.weight AS INTEGER) > 190 GROUP BY T1.playerID ORDER BY SUM(CAST(T2.GA AS INTEGER)) DESC LIMIT 1;
SELECT SUM(CASE WHEN T1.year = 2006 THEN CAST(T1.W AS REAL) * 100 / (T1.W + T1.L) ELSE 0 END) - ( SELECT CAST(W AS REAL) * 100 / (W + L) FROM Teams WHERE year = '2005' AND name = 'Vancouver Canucks' ) FROM Teams AS T1 INNER JOIN Coaches AS T2 ON T1.tmID = T2.tmID AND T1.year = T2.year INNER JOIN Master AS T3 ON T2.coachID = T3.coachID WHERE T1.name = 'Vancouver Canucks' AND T3.firstName = 'Alain' AND T3.lastName = 'Vigneault'
