SELECT M.nameGiven || ' ' || M.lastName AS fullName, MAX(totalAssists) FROM (SELECT S.playerID, SUM(S.A) AS totalAssists FROM Scoring S WHERE S.lgID = 'NHL' GROUP BY S.playerID) AS SubQuery JOIN Master M ON SubQuery.playerID = M.playerID;
