SELECT COUNT(DISTINCT T1.date) FROM sales_in_weather T1 JOIN relation T2 ON T1.store_nbr = T2.store_nbr JOIN weather T3 ON T2.station_nbr = T3.station_nbr WHERE T1.store_nbr = 3 AND T1.item_nbr = 5 AND T1.units > 100 AND T3.tmax > 90;
SELECT T3.units FROM sales_in_weather T3 WHERE T3.item_nbr = 5 AND T3.store_nbr = 3 AND T3.date = (SELECT T1.date FROM weather T1 JOIN relation T2 ON T1.station_nbr = T2.station_nbr WHERE T2.store_nbr = 3 ORDER BY (T1.tmax - T1.tmin) DESC LIMIT 1)
