SELECT TOTAL(units) FROM sales_in_weather, relation, weather WHERE sales_in_weather.store_nbr = relation.store_nbr AND relation.station_nbr = weather.station_nbr AND sales_in_weather.date = weather.date AND sales_in_weather.store_nbr = 3 AND sales_in_weather.item_nbr = 5 AND weather.preciptotal > 0.05;
SELECT T1.date FROM sales_in_weather T1 JOIN relation T2 ON T1.store_nbr = T2.store_nbr JOIN weather T3 ON T2.station_nbr = T3.station_nbr WHERE T1.item_nbr = 5 AND T1.store_nbr = 3 AND T1.units > 100 AND T3.avgspeed > 10 AND T1.date = T3.date
