WITH HighestTemp AS (SELECT date FROM weather WHERE tmax = (SELECT MAX(tmax) FROM weather WHERE SUBSTR(date, 1, 4) = '2012')) SELECT SUM(CASE WHEN store_nbr = 5 THEN units ELSE 0 END) - SUM(CASE WHEN store_nbr = 10 THEN units ELSE 0 END) AS difference FROM sales_in_weather WHERE item_nbr = 16 AND date IN (SELECT date FROM HighestTemp);
