SELECT (COUNT(*) FILTER (WHERE T2.index_code = 'I') * 100.0 / COUNT(*)) AS percentage_severe FROM Crime T1 JOIN IUCR T2 ON T1.iucr_no = T2.iucr_no;
SELECT location_description FROM Crime, District WHERE Crime.district_no = District.district_no AND District.district_name = 'Austin' GROUP BY location_description HAVING COUNT(case_number) = (SELECT MAX(cnt) FROM (SELECT COUNT(case_number) AS cnt FROM Crime WHERE district_no IN (SELECT district_no FROM District WHERE district_name = 'Austin') GROUP BY location_description));
