SELECT community_area_no FROM Crime WHERE location_description = 'STREET' GROUP BY community_area_no HAVING COUNT(*) = (SELECT MAX(cnt) FROM (SELECT COUNT(*) as cnt FROM Crime WHERE location_description = 'STREET' GROUP BY community_area_no));
SELECT AVG(RecklessCount) FROM (SELECT COUNT(C.report_no) AS RecklessCount FROM Crime C JOIN IUCR I ON C.iucr_no = I.iucr_no WHERE I.secondary_description = 'RECKLESS HOMICIDE' GROUP BY C.district_no)
SELECT W.ward_office_address, W.ward_office_phone FROM Ward W INNER JOIN (SELECT ward_no FROM Crime WHERE arrest = 'FALSE' GROUP BY ward_no HAVING COUNT(*) = (SELECT MAX(crime_count) FROM (SELECT ward_no, COUNT(*) as crime_count FROM Crime WHERE arrest = 'FALSE' GROUP BY ward_no) T)) T ON W.ward_no = T.ward_no;
