WITH MinIBU AS (SELECT MIN(ibu) AS min_ibu FROM beers WHERE ibu IS NOT NULL), LowestBitternessStates AS (SELECT T2.state FROM beers T1 JOIN breweries T2 ON T1.brewery_id = T2.id WHERE T1.ibu = (SELECT min_ibu FROM MinIBU)) SELECT DISTINCT state FROM LowestBitternessStates
