WITH MaxIbu AS (SELECT MAX(ibu) AS MaxIbu FROM beers), MinIbu AS (SELECT MIN(ibu) AS MinIbu FROM beers) SELECT breweries.city, breweries.state, beers.name, (MaxIbu.MaxIbu - MinIbu.MinIbu) AS ibu_difference FROM breweries JOIN beers ON breweries.id = beers.brewery_id, MaxIbu, MinIbu WHERE beers.ibu = MaxIbu.MaxIbu OR beers.ibu = MinIbu.MinIbu
