SELECT T1.title, T1.prep_min + T1.cook_min + T1.stnd_min FROM Recipe AS T1 INNER JOIN Nutrition AS T2 ON T1.recipe_id = T2.recipe_id ORDER BY T2.total_fat DESC LIMIT 1
SELECT title FROM Recipe WHERE recipe_id IN (SELECT recipe_id FROM Quantity WHERE ingredient_id = (SELECT ingredient_id FROM Ingredient WHERE name = 'almond extract'));
SELECT T3.name FROM Recipe AS T1 INNER JOIN Quantity AS T2 ON T1.recipe_id = T2.recipe_id INNER JOIN Ingredient AS T3 ON T3.ingredient_id = T2.ingredient_id WHERE T1.title = 'Tomato-Cucumber Relish'
SELECT COUNT(DISTINCT T2.ingredient_id) FROM Recipe T1 JOIN Quantity T2 ON T1.recipe_id = T2.recipe_id WHERE T1.title = 'Idaho Potato Supreme';
SELECT name FROM Ingredient WHERE ingredient_id IN (SELECT ingredient_id FROM Quantity WHERE recipe_id = (SELECT recipe_id FROM Nutrition WHERE carbo = (SELECT MAX(carbo) FROM Nutrition)) AND max_qty = min_qty);
SELECT T1.title FROM Recipe AS T1 INNER JOIN Nutrition AS T2 ON T1.recipe_id = T2.recipe_id WHERE T2.iron > 20
SELECT T1.name FROM Ingredient AS T1 INNER JOIN Quantity AS T2 ON T1.ingredient_id = T2.ingredient_id INNER JOIN Nutrition AS T3 ON T3.recipe_id = T2.recipe_id ORDER BY T3.vitamin_a DESC LIMIT 1
SELECT T3.name, T2.max_qty FROM Recipe AS T1 INNER JOIN Quantity AS T2 ON T1.recipe_id = T2.recipe_id INNER JOIN Ingredient AS T3 ON T3.ingredient_id = T2.ingredient_id WHERE T1.servings = 7
SELECT CAST(SUM(CASE WHEN T2.sodium < 5 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM Recipe AS T1 INNER JOIN Nutrition AS T2 ON T1.recipe_id = T2.recipe_id WHERE T1.source = 'The California Tree Fruit Agreement'
SELECT name FROM Ingredient WHERE ingredient_id IN (SELECT ingredient_id FROM Quantity WHERE unit = 'slice(s)');
SELECT COUNT(DISTINCT T2.recipe_id) FROM Ingredient T1 JOIN Quantity T2 ON T1.ingredient_id = T2.ingredient_id WHERE T1.category = 'canned dairy';
SELECT T2.title, (T2.prep_min + T2.cook_min + T2.stnd_min) AS total_time FROM Recipe T2 JOIN (SELECT recipe_id FROM Quantity GROUP BY recipe_id HAVING COUNT(DISTINCT ingredient_id) = 1 AND MAX(ingredient_id) = (SELECT ingredient_id FROM Ingredient WHERE name = 'lima beans')) T3 ON T2.recipe_id = T3.recipe_id
SELECT CAST(SUM(CASE WHEN T1.servings >= 10 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM Recipe AS T1 INNER JOIN Quantity AS T2 ON T1.recipe_id = T2.recipe_id INNER JOIN Ingredient AS T3 ON T3.ingredient_id = T2.ingredient_id WHERE T3.name = 'sea bass steak'
SELECT T2.total_fat FROM Recipe AS T1 INNER JOIN Nutrition AS T2 ON T1.recipe_id = T2.recipe_id WHERE T1.title = 'Raspberry Chiffon Pie'
SELECT pcnt_cal_prot FROM Recipe AS T1 INNER JOIN Nutrition AS T2 ON T1.recipe_id = T2.recipe_id WHERE T1.title = 'Raspberry Chiffon Pie'
SELECT COUNT(DISTINCT T2.ingredient_id) FROM Recipe T1 JOIN Quantity T2 ON T1.recipe_id = T2.recipe_id WHERE T1.title = 'Raspberry Chiffon Pie';
SELECT T1.title FROM Recipe AS T1 INNER JOIN Nutrition AS T2 ON T1.recipe_id = T2.recipe_id WHERE T2.alcohol = 0
SELECT AVG(T1.vitamin_c) FROM Nutrition AS T1 INNER JOIN Recipe AS T2 ON T2.recipe_id = T1.recipe_id WHERE T2.title LIKE '%cake%'
SELECT COUNT(DISTINCT T2.recipe_id) FROM Ingredient T1 JOIN Quantity T3 ON T1.ingredient_id = T3.ingredient_id JOIN Recipe T2 ON T3.recipe_id = T2.recipe_id WHERE T1.category = 'dairy' AND T2.servings > 10;
SELECT T1.title FROM Recipe AS T1 INNER JOIN Nutrition AS T2 ON T1.recipe_id = T2.recipe_id WHERE T2.iron > 20
SELECT T1.title FROM Recipe AS T1 INNER JOIN Nutrition AS T2 ON T1.recipe_id = T2.recipe_id ORDER BY T2.calories DESC LIMIT 1
SELECT COUNT(DISTINCT T1.recipe_id) FROM Quantity T1 JOIN Ingredient T2 ON T1.ingredient_id = T2.ingredient_id WHERE T2.category NOT LIKE '%dairy';
SELECT name FROM Ingredient WHERE ingredient_id IN (SELECT ingredient_id FROM Quantity WHERE recipe_id = (SELECT recipe_id FROM Recipe WHERE title = 'Apricot Yogurt Parfaits'));
SELECT T2.recipe_id FROM Quantity T1 JOIN Recipe T2 ON T1.recipe_id = T2.recipe_id WHERE T1.max_qty <> T1.min_qty;
SELECT name FROM Ingredient WHERE ingredient_id IN (SELECT ingredient_id FROM Quantity WHERE recipe_id = (SELECT recipe_id FROM Recipe ORDER BY cook_min DESC LIMIT 1))
SELECT CAST(SUM(CASE WHEN T1.cook_min < 20 AND T2.cholestrl = 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) FROM Recipe AS T1 INNER JOIN Nutrition AS T2 ON T1.recipe_id = T2.recipe_id
SELECT (100.0 * COUNT(DISTINCT CASE WHEN T3.calories > 200 THEN T2.recipe_id END) / COUNT(DISTINCT T2.recipe_id)) AS percentage FROM Ingredient T1 JOIN Quantity T2 ON T1.ingredient_id = T2.ingredient_id JOIN Nutrition T3 ON T2.recipe_id = T3.recipe_id WHERE T1.category = 'cheese' AND T3.calories IS NOT NULL;
SELECT firstname || ' ' || lastname AS full_name FROM employee WHERE salary = (SELECT MAX(salary) FROM employee);
SELECT COUNT(*) FROM employee WHERE performance = 'Good'
SELECT ssn FROM employee WHERE gender = 'M' AND CAST(REPLACE(SUBSTR(salary, 4), ',', '') AS REAL) > 70000
SELECT educationrequired FROM position WHERE positiontitle = 'Regional Manager'
