SELECT DISTINCT T2.zipcode FROM employee T1 JOIN location T2 ON T1.locationID = T2.locationID WHERE T1.gender = 'M' AND T1.performance = 'Good' AND NOT EXISTS (SELECT 1 FROM employee T3 WHERE T3.gender = 'M' AND T3.performance != 'Good' AND T3.locationID = T1.locationID)
