SELECT COUNT(T1.id) FROM trip AS T1 INNER JOIN weather AS T2 ON T2.zip_code = T1.zip_code WHERE T1.subscription_type = 'Subscriber' AND T2.min_visibility_miles = 4 AND T1.duration < 490 AND T1.start_station_name = '2nd at Folsom' AND T1.end_station_name = 'Civic Center BART (7th at Market)'
SELECT T2.docks_available FROM trip T1 JOIN status T2 ON T1.start_station_id = T2.station_id WHERE T1.id = 912900;
SELECT T1.id FROM trip T1 JOIN weather T2 ON date(T1.end_date) = T2.date WHERE T2.min_temperature_f < 45;
SELECT MIN(T1.duration) AS ShortestDuration, AVG(T1.duration) AS AverageDuration, (AVG(T1.duration) - MIN(T1.duration)) AS Difference, T2.min_temperature_f, T2.max_gust_speed_mph, T2.events FROM trip T1 JOIN weather T2 ON strftime('%m/%d/%Y', T1.start_date) = T2.date WHERE T1.subscription_type = 'Subscriber' AND T1.start_station_name = '2nd at Folsom' AND T1.end_station_name = '5th at Howard' AND T1.start_date >= '1/1/2014 0:00' AND T1.end_date <= '12/31/2014 11:59' GROUP BY T2.date
SELECT AVG(duration) FROM trip WHERE start_date = '7/1/2014%' AND end_date = '7/31/2014%' AND start_station_name = 'Steuart at Market' AND end_station_name = 'Embarcadero at Sansome'
SELECT AVG(max_temperature_f), AVG(min_temperature_f) FROM weather WHERE date LIKE '5/%/2015' AND mean_humidity BETWEEN 65 AND 75
SELECT COUNT(CASE WHEN subscription_type = 'Subscriber' THEN 1 END) - COUNT(CASE WHEN subscription_type = 'Customer' THEN 1 END) AS difference FROM trip WHERE strftime('%m/%Y', start_date) = '06/2013';
SELECT T2.bike_id FROM weather T1 JOIN trip T2 ON strftime('%m/%d/%Y', T1.date) = strftime('%m/%d/%Y', T2.start_date) WHERE T1.events = 'Fog-Rain' AND strftime('%Y', T1.date) = '2013';
SELECT T2.mean_visibility_miles, T2.mean_wind_speed_mph, T2.events, T3.name AS start_station_name, T3.lat AS start_station_lat, T3.long AS start_station_long, T4.name AS end_station_name, T4.lat AS end_station_lat, T4.long AS end_station_long FROM trip T1 JOIN weather T2 ON strftime('%m/%d/%Y', T1.start_date) = T2.date JOIN station T3 ON T1.start_station_id = T3.id JOIN station T4 ON T1.end_station_id = T4.id WHERE T2.events = 'fog' ORDER BY T1.duration DESC LIMIT 1
SELECT T1.start_date FROM trip AS T1 INNER JOIN weather AS T2 ON T2.zip_code = T1.zip_code AND T2.date = SUBSTR(CAST(T1.start_date AS TEXT), 1, INSTR(T1.start_date, ' ') - 1) WHERE T2.date LIKE '8/%/2013' AND T1.start_station_name = 'Market at 10th' AND T1.end_station_name = 'South Van Ness at Market' AND T2.min_temperature_f = ( SELECT MIN(T2.min_temperature_f) FROM trip AS T1 INNER JOIN weather AS T2 ON T2.zip_code = T1.zip_code AND T2.date = SUBSTR(CAST(T1.start_date AS TEXT), 1, INSTR(T1.start_date, ' ') - 1) WHERE T2.date LIKE '8/%/2013' AND T1.start_station_name = 'Market at 10th' AND T1.end_station_name = 'South Van Ness at Market' )
SELECT T1.start_station_name, T1.end_station_name, T1.duration FROM trip T1 JOIN weather T2 ON T1.start_date LIKE T2.date || '%' WHERE T2.events = 'rain' ORDER BY T1.duration DESC LIMIT 1;
SELECT AVG(duration) FROM trip WHERE SUBSTR(start_date, 1, INSTR(start_date, ' ') - 1) IN (SELECT date FROM weather WHERE events = 'rain' AND CAST(precipitation_inches AS FLOAT) > 0.8);
SELECT DISTINCT T1.start_station_name, T2.city FROM trip AS T1 INNER JOIN station AS T2 ON T2.name = T1.start_station_name WHERE T1.duration > ( SELECT AVG(T1.duration) FROM trip AS T1 LEFT JOIN station AS T2 ON T2.name = T1.start_station_name )
SELECT SUM(CASE WHEN city = 'San Francisco' AND SUBSTR(installation_date, -4) = '2014' THEN 1 ELSE 0 END) FROM station
