SELECT bike_id, SUM(duration)/3600 AS total_hours FROM trip INNER JOIN station StartStation ON trip.start_station_id = StartStation.id INNER JOIN station EndStation ON trip.end_station_id = EndStation.id WHERE StartStation.city = EndStation.city GROUP BY bike_id HAVING total_hours = (SELECT MIN(total_hours) FROM (SELECT SUM(duration)/3600 AS total_hours FROM trip INNER JOIN station StartStation ON trip.start_station_id = StartStation.id INNER JOIN station EndStation ON trip.end_station_id = EndStation.id WHERE StartStation.city = EndStation.city GROUP BY bike_id) AS MinHours);
